CREATE DATABASE IF NOT EXISTS alerta_vecinos CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE alerta_vecinos;
CREATE TABLE usuarios (id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,celular VARCHAR(30) NOT NULL,correo VARCHAR(150) NOT NULL UNIQUE,contrasena VARCHAR(255) NOT NULL,lat DECIMAL(10,7) NULL,lng DECIMAL(10,7) NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE incidentes (id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(40) NOT NULL UNIQUE,usuario_id INT NOT NULL,tipo VARCHAR(80) NOT NULL,descripcion TEXT NOT NULL,ubicacion VARCHAR(255) NOT NULL,lat DECIMAL(10,7) NULL,lng DECIMAL(10,7) NULL,evidencia_nombre VARCHAR(255) NULL,evidencia_tipo VARCHAR(100) NULL,evidencia_datos LONGTEXT NULL,estado ENUM('Activo','Resuelto') DEFAULT 'Activo',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_inc_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE confirmaciones (id INT AUTO_INCREMENT PRIMARY KEY,incidente_id INT NOT NULL,usuario_id INT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_confirmacion (incidente_id, usuario_id),CONSTRAINT fk_conf_inc FOREIGN KEY (incidente_id) REFERENCES incidentes(id) ON DELETE CASCADE,CONSTRAINT fk_conf_user FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
